"""Command-line regression tests for the Module Manager ELF converters.

The fixtures are deliberately small synthetic ELF32 files. They let the test
exercise malformed offsets and headers that a normal linker would never emit.
Only Python's standard library is required.
"""

import os
import re
import shutil
import struct
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path


ELF_HEADER_SIZE = 52
PROGRAM_HEADER_SIZE = 32
SECTION_HEADER_SIZE = 40
ELF_IDENT = b"\x7fELF" + bytes((1, 1, 1, 0, 0)) + bytes(7)
SHSTRTAB = b"\x00.text\x00.text2\x00.shstrtab\x00"
TEXT_NAME = 1
TEXT2_NAME = 7
SHSTRTAB_NAME = 14
CONVERTER_ARGUMENTS = []


def pack_ehdr(*, endian="<", phnum=1, phoff=ELF_HEADER_SIZE,
              shoff=None, shnum=3, shstrndx=2, phentsize=PROGRAM_HEADER_SIZE,
              shentsize=SECTION_HEADER_SIZE, ehsize=ELF_HEADER_SIZE,
              ident=None, version=1, ident_version=1):
    if shoff is None:
        shoff = 0
    if ident is None:
        ident = bytearray(ELF_IDENT)
    else:
        ident = bytearray(ident)
    ident[6] = ident_version
    return struct.pack(
        endian + "16sHHIIIIIHHHHHH", bytes(ident), 2, 40, version, 0,
        phoff, shoff, 0, ehsize, phentsize, phnum, shentsize, shnum,
        shstrndx)


def pack_phdr(endian="<"):
    # PT_LOAD; its contents are not interpreted by these utilities.
    return struct.pack(endian + "IIIIIIII", 1, ELF_HEADER_SIZE + PROGRAM_HEADER_SIZE,
                       0, 0, 0, 0, 5, 4)


def pack_shdr(endian="<", name=0, section_type=0, flags=0, address=0,
              offset=0, size=0, link=0, info=0, align=1, entsize=0):
    return struct.pack(endian + "IIIIIIIIII", name, section_type, flags,
                       address, offset, size, link, info, align, entsize)


def make_elf(*, sections=None, phnum=1, endian="<", ident=None,
             ident_version=1, header_overrides=None):
    """Create an ELF32 input with section specs (name, vaddr, bytes)."""
    if sections is None:
        sections = [(".text", 0x1000, b"\x11\x22\x33\x44")]

    program = pack_phdr(endian) if phnum else b""
    data = bytearray(ELF_HEADER_SIZE + len(program))
    data[ELF_HEADER_SIZE:] = program
    section_headers = [pack_shdr(endian)]
    name_offsets = {".text": TEXT_NAME, ".text2": TEXT2_NAME}
    for name, address, contents in sections:
        section_offset = len(data)
        data.extend(contents)
        section_headers.append(pack_shdr(
            endian, name=name_offsets[name], section_type=1, flags=0x6,
            address=address, offset=section_offset, size=len(contents), align=4))

    names_offset = len(data)
    data.extend(SHSTRTAB)
    section_headers.append(pack_shdr(
        endian, name=SHSTRTAB_NAME, section_type=3, offset=names_offset,
        size=len(SHSTRTAB), align=1))
    shoff = len(data)
    data.extend(b"".join(section_headers))
    ehdr = pack_ehdr(endian=endian, phnum=phnum,
                     phoff=ELF_HEADER_SIZE if phnum else 0,
                     shoff=shoff, shnum=len(section_headers),
                     shstrndx=len(section_headers) - 1,
                     ident=ident, ident_version=ident_version)
    data[:ELF_HEADER_SIZE] = ehdr

    for offset, value, fmt in (header_overrides or []):
        struct.pack_into(endian + fmt, data, offset, value)
    return bytes(data)


def run_converter(executable, input_path, output_path, *, env=None):
    return subprocess.run([str(executable), str(input_path), str(output_path)],
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                          text=True, env=env, check=False)


def c_array_bytes(path):
    text = path.read_text(encoding="utf-8")
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.DOTALL)
    match = re.search(r"module_code\[\]\s*=\s*\{(.*?)\};", text,
                      flags=re.DOTALL)
    if not match:
        raise AssertionError("module_code array was not emitted")
    return bytes(int(value, 16) for value in
                 re.findall(r"0x([0-9A-Fa-f]{1,2})\b", match.group(1)))


# ISSUE #585 TESTS: exercise both converter programs against valid and hostile
# ELF fixtures, including deterministic allocation-failure injection.
class ModuleConverterELF32Tests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.binary_converter = Path(CONVERTER_ARGUMENTS[0]).resolve()
        cls.array_converter = Path(CONVERTER_ARGUMENTS[1]).resolve()
        cls.source_binary = Path(CONVERTER_ARGUMENTS[2]).resolve()
        cls.source_array = Path(CONVERTER_ARGUMENTS[3]).resolve()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="threadx-elf32-")
        self.directory = Path(self.temp.name)
        self.input_path = self.directory / "fixture.elf"

    def tearDown(self):
        self.temp.cleanup()

    def write_fixture(self, contents):
        self.input_path.write_bytes(contents)
        return self.input_path

    def assert_both_succeed(self, contents, expected):
        self.write_fixture(contents)
        binary_path = self.directory / "module.bin"
        array_path = self.directory / "module.c"
        for converter, output in ((self.binary_converter, binary_path),
                                  (self.array_converter, array_path)):
            result = run_converter(converter, self.input_path, output)
            self.assertEqual(result.returncode, 0,
                             msg=result.stdout + result.stderr)
        self.assertEqual(binary_path.read_bytes(), expected)
        self.assertEqual(c_array_bytes(array_path), expected)

    def assert_both_reject(self, contents):
        self.write_fixture(contents)
        for converter, output in (
                (self.binary_converter, self.directory / "rejected.bin"),
                (self.array_converter, self.directory / "rejected.c")):
            result = run_converter(converter, self.input_path, output)
            self.assertNotEqual(result.returncode, 0,
                                msg="converter unexpectedly accepted fixture")

    def test_v1_valid_elf32_little_endian(self):
        self.assert_both_succeed(make_elf(), b"\x11\x22\x33\x44")

    def test_v2_sections_are_sorted_and_gap_is_zero_filled(self):
        contents = make_elf(sections=[
            (".text2", 0x1006, b"\xA1\xA2"),
            (".text", 0x1000, b"\x01\x02\x03")])
        self.assert_both_succeed(
            contents, b"\x01\x02\x03\x00\x00\x00\xA1\xA2")

    def test_v3_zero_program_headers(self):
        self.assert_both_succeed(make_elf(phnum=0), b"\x11\x22\x33\x44")

    @unittest.skipUnless(shutil.which("readelf") or shutil.which("llvm-readelf"),
                         "readelf/llvm-readelf is not installed")
    def test_v4_readelf_independent_header_and_section_cross_check(self):
        self.write_fixture(make_elf(sections=[
            (".text", 0x1000, b"\x11\x22"),
            (".text2", 0x1008, b"\x33")]))
        readelf = shutil.which("readelf") or shutil.which("llvm-readelf")
        result = subprocess.run([readelf, "-h", "-S",
                                 str(self.input_path)], stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, text=True, check=False)
        self.assertEqual(result.returncode, 0, msg=result.stderr)
        self.assertIn("ELF32", result.stdout)
        self.assertIn("little endian", result.stdout.lower())
        self.assertRegex(result.stdout, r"\.text\s+PROGBITS\s+(?:0x)?0*1000\b")
        self.assertRegex(result.stdout, r"\.text2\s+PROGBITS\s+(?:0x)?0*1008\b")
        self.assertIn(".shstrtab", result.stdout)
        self.assertRegex(result.stdout, r"Number of section headers:\s+4\b")
        self.assertRegex(result.stdout, r"Size of section headers:\s+40\b")

    def test_r1_bad_and_missing_magic(self):
        for magic in (b"NOPE", b"\x00\x00\x00\x00"):
            contents = bytearray(make_elf())
            contents[:4] = magic
            with self.subTest(magic=magic):
                self.assert_both_reject(bytes(contents))

    def test_r2_elf64_class_rejected(self):
        contents = bytearray(make_elf())
        contents[4] = 2
        self.assert_both_reject(bytes(contents))

    def test_r3_big_endian_elf32_rejected(self):
        ident = bytearray(ELF_IDENT)
        ident[5] = 2
        self.assert_both_reject(make_elf(endian=">", ident=ident))

    def test_r4_invalid_ident_and_header_versions_rejected(self):
        cases = [make_elf(ident_version=0),
                 make_elf(header_overrides=[(20, 0, "I")])]
        for contents in cases:
            with self.subTest(version=contents[6]):
                self.assert_both_reject(contents)

    def test_r5_wrong_elf_record_sizes_rejected(self):
        for offset, value in ((40, 51), (42, 31), (46, 39)):
            contents = bytearray(make_elf())
            struct.pack_into("<H", contents, offset, value)
            with self.subTest(offset=offset):
                self.assert_both_reject(bytes(contents))

    def test_r6_short_header_rejected(self):
        self.assert_both_reject(b"\x7fELF" + bytes(47))

    def test_r7_program_header_table_outside_file_rejected(self):
        contents = bytearray(make_elf())
        struct.pack_into("<I", contents, 28, 0xFFFFFFF0)
        self.assert_both_reject(bytes(contents))

    def test_r8_truncated_section_header_table_rejected(self):
        contents = bytearray(make_elf())
        struct.pack_into("<I", contents, 32, len(contents) - 8)
        self.assert_both_reject(bytes(contents))

    def test_r9_invalid_section_string_table_index_rejected(self):
        contents = bytearray(make_elf())
        struct.pack_into("<H", contents, 50, 0xFFFF)
        self.assert_both_reject(bytes(contents))

    def test_r10_string_table_and_code_section_past_eof_rejected(self):
        fixture = make_elf()
        shoff = struct.unpack_from("<I", fixture, 32)[0]
        cases = []
        # The final section header is the section-name string table.
        bad_names = bytearray(fixture)
        struct.pack_into("<I", bad_names, shoff + 2 * SECTION_HEADER_SIZE + 16,
                         len(fixture) - 1)
        struct.pack_into("<I", bad_names, shoff + 2 * SECTION_HEADER_SIZE + 20,
                         len(SHSTRTAB))
        cases.append(bytes(bad_names))
        # The .text section content is also moved to a range past EOF.
        bad_text = bytearray(fixture)
        struct.pack_into("<I", bad_text, shoff + SECTION_HEADER_SIZE + 16,
                         len(fixture) - 1)
        cases.append(bytes(bad_text))
        for contents in cases:
            self.assert_both_reject(contents)

    def test_r11_large_counts_and_offsets_fail_without_wraparound(self):
        cases = []
        huge_phdr = bytearray(make_elf())
        struct.pack_into("<I", huge_phdr, 28, 0xFFFFFFF0)
        struct.pack_into("<H", huge_phdr, 44, 0xFFFF)
        cases.append(bytes(huge_phdr))
        huge_shdr = bytearray(make_elf())
        struct.pack_into("<I", huge_shdr, 32, 0xFFFFFFFF)
        struct.pack_into("<H", huge_shdr, 48, 0xFFFF)
        cases.append(bytes(huge_shdr))
        for contents in cases:
            self.assert_both_reject(contents)

    def test_r12_invalid_source_and_output_paths_report_failure(self):
        missing = self.directory / "does-not-exist.elf"
        for converter in (self.binary_converter, self.array_converter):
            missing_result = run_converter(
                converter, missing, self.directory / "out.bin")
            self.assertNotEqual(missing_result.returncode, 0)
            self.assertIn("open failed", missing_result.stdout.lower())

        self.write_fixture(make_elf())
        missing_directory = self.directory / "missing" / "output"
        for converter in (self.binary_converter, self.array_converter):
            output_result = run_converter(
                converter, self.input_path, missing_directory)
            self.assertNotEqual(output_result.returncode, 0)
            self.assertIn("open failed", output_result.stdout.lower())

    def test_r13_allocation_failure_injection(self):
        """Rebuild with a malloc shim and fail each observed allocation."""
        compiler = os.environ.get("CC", "cc")
        shim = self.directory / "malloc_fail.c"
        shim.write_text(
            "#include <stddef.h>\n"
            "#include <stdlib.h>\n"
            "#include <string.h>\n"
            "static unsigned long calls;\n"
            "void *module_test_malloc(size_t size) {\n"
            "  const char *setting = getenv(\"MODULE_TEST_FAIL_MALLOC_AT\");\n"
            "  unsigned long fail_at = setting ? strtoul(setting, NULL, 10) : 0;\n"
            "  calls++;\n"
            "  if (fail_at == calls) return NULL;\n"
            "  return malloc(size);\n"
            "}\n", encoding="utf-8")
        fixture = self.write_fixture(make_elf(sections=[
            (".text", 0x1000, b"\x01\x02"),
            (".text2", 0x1004, b"\x03\x04")]))

        for source in (self.source_binary, self.source_array):
            obj = self.directory / (source.stem + ".o")
            injected = self.directory / (source.stem + "_malloc_fail")
            compile_source = subprocess.run(
                [compiler, "-std=c99", "-Dmalloc=module_test_malloc", "-c",
                 str(source), "-o", str(obj)], stdout=subprocess.PIPE,
                stderr=subprocess.PIPE, text=True, check=False)
            self.assertEqual(compile_source.returncode, 0,
                             msg=compile_source.stdout + compile_source.stderr)
            compile_shim = subprocess.run(
                [compiler, "-std=c99", "-c", str(shim), "-o",
                 str(self.directory / "malloc_fail.o")],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                text=True, check=False)
            self.assertEqual(compile_shim.returncode, 0,
                             msg=compile_shim.stdout + compile_shim.stderr)
            link = subprocess.run(
                [compiler, str(obj), str(self.directory / "malloc_fail.o"),
                 "-o", str(injected)], stdout=subprocess.PIPE,
                stderr=subprocess.PIPE, text=True, check=False)
            self.assertEqual(link.returncode, 0, msg=link.stdout + link.stderr)

            # The valid fixture causes seven allocations: program headers,
            # raw/decoded section tables, string table, section list and two
            # section buffers. Each forced failure must be handled as an error.
            for allocation_index in range(1, 8):
                output = self.directory / (source.stem + "_failure.out")
                env = os.environ.copy()
                env["MODULE_TEST_FAIL_MALLOC_AT"] = str(allocation_index)
                result = run_converter(injected, fixture, output, env=env)
                self.assertNotEqual(result.returncode, 0,
                                    msg=f"allocation {allocation_index} was not rejected")
                self.assertIn("memory allocation failed", result.stdout.lower())


if __name__ == "__main__":
    CONVERTER_ARGUMENTS = sys.argv[1:5]
    del sys.argv[1:5]
    unittest.main(verbosity=2)
